import {scoped,severity,evaluate,append,acknowledge,seed} from './model.mjs';
const $=id=>document.getElementById(id), devices=seed(), alarms=[];
let line='all',selected=devices[0].id,metric='temperature',minutes=5,paused=false;
const labels={temperature:['溫度','°C'],pressure:['壓力','bar'],vibration:['振動','mm/s']};
const fmt=t=>new Date(t).toLocaleTimeString('zh-TW',{hour12:false});
devices.forEach(d=>evaluate(d,alarms,Date.now()));
function render(){const visible=scoped(devices,line),d=devices.find(d=>d.id===selected),current=d.samples.at(-1),pending=alarms.filter(a=>visible.some(d=>d.id===a.deviceId)&&!a.acknowledged);const avg=visible.reduce((sum,d)=>sum+d.samples.at(-1).temperature,0)/visible.length;
$('kpis').innerHTML=[['設備總數',visible.length,'台','目前選取產線的設備',''],['運轉設備',visible.filter(d=>d.running).length,'台','持續監測中的設備','good'],['未確認告警',pending.length,'則','待值班人員確認','warning'],['平均溫度',avg.toFixed(1),'°C','包含目前範圍內所有設備','']].map(([l,n,u,note,c])=>`<article class="kpi"><div class="kpi-label">${l}<span>↗</span></div><div class="kpi-number ${c}">${n}<small>${u}</small></div><div class="kpi-note">${note}</div></article>`).join('');
$('device-count').textContent=`${visible.length} 台設備`;
$('devices').innerHTML=visible.map(x=>{const status=x.running?severity(x.samples.at(-1).temperature):'停機';return `<button class="device ${x.id===selected?'selected':''}" data-device="${x.id}" aria-pressed="${x.id===selected}"><span class="device-icon">▥</span><span class="device-text"><b>${x.name}</b><small>${x.id} · ${x.line} 產線</small></span><span class="badge ${status==='嚴重'?'danger':status==='警告'?'warn':status==='停機'?'':'ok'}">${status||'運轉中'}</span></button>`}).join('');
$('chart-sub').textContent=`${d.name} / ${d.id} · ${d.line} 產線${d.running?'':' · 設備停機，顯示最後樣本'}`;
$('metrics').innerHTML=Object.entries(labels).map(([key,[label,unit]])=>`<button class="metric ${key===metric?'selected':''}" data-metric="${key}" aria-pressed="${key===metric}"><span>${label}</span><b>${current[key].toFixed(1)} <small>${unit}</small></b></button>`).join('');
const samples=d.samples.filter(s=>s.time>=Date.now()-minutes*60000),values=samples.map(s=>s[metric]),lo=values.length?Math.floor(Math.min(...values)-2):0,hi=values.length?Math.ceil(Math.max(...values)+2):1;const y=v=>195-(v-lo)/(hi-lo)*165;const x=t=>50+(t-(Date.now()-minutes*60000))/(minutes*60000)*690;const points=samples.map(s=>`${x(s.time)},${y(s[metric])}`);
$('chart').innerHTML=`<defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#26ae96" stop-opacity=".18"/><stop offset="1" stop-color="#26ae96" stop-opacity="0"/></linearGradient></defs>${Array.from({length:5},(_,i)=>{const v=lo+(hi-lo)*i/4;return `<line x1="50" x2="740" y1="${y(v)}" y2="${y(v)}" stroke="#e9eef3" stroke-dasharray="4 5"/><text x="39" y="${y(v)+4}" text-anchor="end" font-size="12" fill="#93a0b0">${v.toFixed(1)}</text>`}).join('')}${points.length?`<polygon points="${x(samples[0].time)},195 ${points.join(' ')} ${x(samples.at(-1).time)},195" fill="url(#fill)"/><polyline points="${points.join(' ')}" fill="none" stroke="#159c86" stroke-width="2.5" stroke-linejoin="round"/>`:'<text x="380" y="115" text-anchor="middle" fill="#7c8da0">此時段無樣本</text>'}${[0,1,2,3,4].map(i=>`<text x="${50+i*172.5}" y="226" text-anchor="${i===0?'start':i===4?'end':'middle'}" font-size="12" fill="#93a0b0">${fmt(Date.now()-(4-i)*minutes*15000)}</text>`).join('')}`;
$('legend').textContent=`${labels[metric][0]} (${labels[metric][1]})`;$('updated').textContent=`最後樣本 ${fmt(current.time)}`;
$('alarm-count').textContent=`${pending.length} 待確認`;
const rows=alarms.filter(a=>visible.some(d=>d.id===a.deviceId)&&($('alarm-filter').value==='all'||!a.acknowledged));
$('alarm-rows').innerHTML=rows.length?rows.map(a=>{const d=devices.find(d=>d.id===a.deviceId);return `<tr><td><span class="badge ${a.severity==='嚴重'?'danger':'warn'}">${a.severity}</span></td><td>${d.name} <small> / ${d.line}</small></td><td>${a.message}</td><td>${fmt(a.time)}</td><td>${a.acknowledged?'已確認':'待確認'}</td><td>${a.acknowledged?'—':`<button data-ack="${a.id}">確認告警</button>`}</td></tr>`}).join(''):'<tr><td class="empty" colspan="6">目前沒有符合條件的告警</td></tr>';
}
function selectDevice(id){if(!scoped(devices,line).some(d=>d.id===id))throw Error('設備不在目前產線範圍');selected=id;render();return {selected};}
$('line').onchange=e=>{line=e.target.value;if(!scoped(devices,line).some(d=>d.id===selected))selected=scoped(devices,line)[0].id;render()};
$('range').onchange=e=>{minutes=Number(e.target.value);render()};$('alarm-filter').onchange=render;
$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'▶ 啟動模擬':'Ⅱ 暫停模擬';$('live').textContent=paused?'模擬已暫停':'模擬運行中';};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.device)selectDevice(b.dataset.device);if(b.dataset.metric){metric=b.dataset.metric;render()}if(b.dataset.ack){acknowledge(alarms,b.dataset.ack);render();$('toast').textContent='告警已確認，仍持續監測設備狀態';$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',2500)}});
render();setInterval(()=>{if(paused)return;const now=Date.now();devices.filter(d=>d.running).forEach((d,i)=>{const s=d.samples.at(-1);append(d,{time:now,temperature:Math.max(20,Math.min(102,s.temperature+(Math.random()-.5)*1.3)),pressure:Math.max(.1,s.pressure+(Math.random()-.5)*.04),vibration:Math.max(.1,s.vibration+(Math.random()-.5)*.08)});evaluate(d,alarms,now)});render()},2000);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'select_monitoring_device',description:'選取目前產線範圍中的設備並更新可見趨勢。',inputSchema:{type:'object',properties:{deviceId:{type:'string'}},required:['deviceId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.deviceId!=='string'||Object.keys(input).some(k=>k!=='deviceId'))throw Error('需要 deviceId');return selectDevice(input.deviceId)}},{signal:lifecycle.signal})).catch(()=>{});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}}
